/bin/bash -c "python3 - <<'PY'
import math,itertools

def mm(A,B):
    return [[sum(a*b for a,b in zip(row,col)) for col in zip(*B)] for row in A]
def tr(A):
    return [list(c) for c in zip(*A)]
def add(A,B):
    return [[a+b for a,b in zip(x,y)] for x,y in zip(A,B)]
def scale(a,A):
    return [[a*x for x in row] for row in A]
def dot(A,B):
    return sum(a*b for x,y in zip(A,B) for a,b in zip(x,y))
def norm(A):
    return math.sqrt(dot(A,A))
q=1/math.sqrt(2)
X=[[0,q,q],[q,-.5,.5],[q,.5,-.5]]
Omega=scale(.25,[[0,1,-1],[-1,0,0],[1,0,0]])
A=mm(Omega,X)
S=[[0 if x==0 else (1 if x>0 else -1) for x in row] for row in X]
C=add(A,scale(-1,S))
I=[[int(i==j) for j in range(3)] for i in range(3)]
def F(Y):
    return dot(C,Y)+sum(abs(x) for row in Y for x in row)
print('X orthogonality residual:',norm(add(mm(tr(X),X),scale(-1,I))))
print('F(X):',F(X))
print('C:',C)
for i,j in itertools.combinations(range(3),2):
    for determinant in [1,-1]:
        best=(float('inf'),None)
        for z in range(10001):
            theta=2*math.pi*z/10000
            c,s=math.cos(theta),math.sin(theta)
            V=[[c,s],[-s,c]] if determinant==1 else [[-c,s],[s,c]]
            W=[row[:] for row in I]
            W[i][i],W[i][j],W[j][i],W[j][j]=V[0][0],V[0][1],V[1][0],V[1][1]
            diff=F(mm(W,X))-F(X)
            if diff<best[0]:best=(diff,theta)
        print('pair', (i+1,j+1),'det',determinant,'minimum F difference on grid',best)
for z in [-q,0,q]:
    G=[row[:] for row in A]
    G[0][0]+=z
    D=add(mm(G,tr(X)),scale(-1,mm(X,tr(G))))
    print('subgradient z',z,'D12',D[0][1],'D13',D[0][2],'stationarity residual',norm(D))
w=math.sqrt(2)*.25
for t in [1e-4,1e-3,.01]:
    W=add(add(I,scale(-math.sin(w*t)/w,Omega)),scale((1-math.cos(w*t))/w**2,mm(Omega,Omega)))
    Y=mm(W,X)
    print('joint step',t,'F difference',F(Y)-F(X),'Y11',Y[0][0],'orthogonality residual',norm(add(mm(tr(Y),Y),scale(-1,I))))
print('Independent Eq 54 counterexample: n=3,r=1,k=2, X=e1, f=x2, h=0')
print('Full residual=1, gamma times mean block residual=',math.sqrt(3)*(math.sqrt(2)/3))
PY"
